        res_0 = requests \
                .get(self.baseUrlOfSut + "/api/v1/provisioning/contact-points/export?" + 
                    "download=false&" + 
                    "format=json&" + 
                    "decrypt=true",
                    headers=headers, cookies=cookies_viewer, timeout=EM_HTTP_TIMEOUT_S, verify=False)
        
        assert res_0.status_code == 403
        assert "application/json" in res_0.headers["content-type"]
