        body = {}
        body = " { " + \
            " \"comment\" : \"iAp82bckkSvrnij2\" " + \
            " } "
        headers['Accept'] = "application/json"
        res_2 = requests \
                .patch(self.baseUrlOfSut + "/api/query-history/mKJSi3F6PZkO",
                    headers=headers, cookies=cookies_viewer, data=body, timeout=EM_HTTP_TIMEOUT_S, verify=False)
        
        assert res_2.status_code == 401
        assert "www-authenticate" not in res_2.headers
        assert "application/json" in res_2.headers["content-type"]
